script:
frappe.ui.form.on("Bank Loan App", {
    refresh: function(frm) {
        if (frm.doc.docstatus !== 0) return;
        if (!frm._bank_loan_btn_set) {
            frm._bank_loan_btn_set = true;
            frm.add_custom_button(__("Generate Loan Schedule"), function() {
                var principal = parseFloat(frm.doc.loan_amount) || 0;
                var rate = parseFloat(frm.doc.interest_rate) || 0;
                var term = parseInt(frm.doc.loan_term_months, 10) || 0;
                var start = frm.doc.repayment_start_date;
                if (!principal || !rate || !term || !start) {
                    frappe.msgprint("Please set Loan Amount, Interest Rate, Loan Term and Repayment Start Date first.");
                    return;
                }
                if (principal <= 0 || term <= 0) {
                    frappe.msgprint("Invalid loan amount or term.");
                    return;
                }
                var months = term;
                var monthlyRate = rate / 12 / 100;
                var emi = 0;
                if (monthlyRate !== 0) {
                    emi = principal * (monthlyRate * Math.pow(1 + monthlyRate, months)) / (Math.pow(1 + monthlyRate, months) - 1);
                } else {
                    emi = principal / months;
                }
                if (!isFinite(emi) || emi < 0) {
                    frappe.msgprint("EMI calculation failed.");
                    return;
                }
                var balance = principal;
                var totalInterest = 0;
                var fmt = function(n) { return Math.round(n * 100) / 100; };
                var addMonths = function(dstr, add) {
                    var parts = dstr.split("-");
                    var y = parseInt(parts[0], 10);
                    var m = parseInt(parts[1], 10) - 1 + add;
                    var d = parseInt(parts[2], 10);
                    var nd = new Date(y, m, d);
                    if (nd.getDate() !== d) nd = new Date(y, m + 1, 0);
                    if (nd.getMonth() + 1 == 13) { nd = new Date(nd.getFullYear()+1, 0, nd.getDate()); }
                    var mm = ("0" + (nd.getMonth() + 1)).slice(-2);
                    var dd = ("0" + nd.getDate()).slice(-2);
                    return nd.getFullYear() + "-" + mm + "-" + dd;
                };
                frm.clear_table("disbursement_schedule");
                frm.clear_table("repayment_schedule");
                frm.clear_table("charges");
                frm.clear_table("documents");
                frm.clear_table("cosigner");
                var disbRow = frm.add_child("disbursement_schedule");
                disbRow.installment_no = 1;
                disbRow.due_date = frm.doc.disbursement_date || start;
                disbRow.principal_amount = principal;
                disbRow.interest_amount = 0;
                disbRow.total_amount = principal;
                disbRow.status = "Scheduled";
                for (var i = 1; i <= months; i++) {
                    var interest = fmt(balance * monthlyRate);
                    var principalComp = 0;
                    var rowEMI = 0;
                    if (i === months) {
                        principalComp = fmt(balance);
                        rowEMI = fmt(balance + interest);
                    } else {
                        principalComp = fmt(emi - interest);
                        rowEMI = fmt(emi);
                    }
                    var balanceAfter = fmt(i === months ? 0 : balance - principalComp);
                    if (balanceAfter < 0) balanceAfter = 0;
                    var due = addMonths(start, i - 1);
                    var repRow = frm.add_child("repayment_schedule");
                    repRow.due_date = due;
                    repRow.payment_date = null;
                    repRow.principal_amount = principalComp;
                    repRow.interest_amount = interest;
                    repRow.total_payment = rowEMI;
                    repRow.balance_after_payment = balanceAfter;
                    repRow.status = "Unpaid";
                    totalInterest += interest;
                    balance = balanceAfter;
                }
                var fallbackAccount = frm.doc.interest_income_account || frm.doc.disbursement_account || "";
                var procRow = frm.add_child("charges");
                procRow.charge_type = "Processing Fee";
                procRow.amount = 0;
                procRow.account = fallbackAccount;
                var docRow = frm.add_child("charges");
                docRow.charge_type = "Documentation";
                docRow.amount = 0;
                docRow.account = fallbackAccount;
                frm.set_value("total_payment", fmt(principal + totalInterest));
                frm.set_value("total_interest_payable", fmt(totalInterest));
                frm.refresh_field("repayment_schedule");
                frm.refresh_field("disbursement_schedule");
                frm.refresh_field("charges");
                frm.refresh_field("total_payment");
                frm.refresh_field("total_interest_payable");
                frappe.call('frappe.client.insert', {
                    doctype: 'Payment Entry',
                    doc: {
                        naming_series: 'ACC-PAY-.YYYY.-',
                        payment_type: 'Receive',
                        company: frm.doc.company || 'JMIT',
                        party_type: 'Customer',
                        party: frm.doc.applicant || '',
                        posting_date: frappe.datetime.get_today(),
                        paid_from: '1310 - Debtors - JMIT',
                        paid_to: '1110 - Cash - JMIT',
                        paid_amount: principal,
                        received_amount: principal,
                        source_exchange_rate: 1,
                        target_exchange_rate: 1,
                        reference_no: frm.doc.name,
                        reference_date: (frm.doc.disbursement_schedule && frm.doc.disbursement_schedule[0] && frm.doc.disbursement_schedule[0].due_date) || frappe.datetime.get_today(),
                        bank_loan_app: frm.doc.name,
                        remarks: 'Loan disbursement for ' + frm.doc.name
                    }
                }).then(function(r){
                    var pe = (r && r.message) || {};
                    if(pe && pe.name){
                        if (frm.doc.disbursement_schedule && frm.doc.disbursement_schedule[0]) {
                            frm.doc.disbursement_schedule[0].payment_entry = pe.name;
                            frm.doc.disbursement_schedule[0].status = 'Disbursed';
                            frm.refresh_field('disbursement_schedule');
                        }
                        frappe.msgprint('Payment Entry ' + pe.name + ' created.');
                        setTimeout(function(){ frappe.open_in_new_tab('/app/payment-entry/' + encodeURIComponent(pe.name)); }, 500);
                        var created = [];
                        var idx = 0;
                        var rows = frm.doc.repayment_schedule || [];
                        function next() {
                            if (idx >= rows.length) {
                                if (created.length) {
                                    frappe.msgprint('Generated ' + created.length + ' Sales Invoice(s).');
                                }
                                setTimeout(function(){ frm.save(); }, 200);
                                return;
                            }
                            var row = rows[idx++];
                            var amt = parseFloat(row.total_payment || 0);
                            if (!amt) { next(); return; }
                            frappe.call('frappe.client.insert', {
                                doctype: 'Sales Invoice',
                                doc: {
                                    naming_series: 'ACC-SINV-.YYYY.-',
                                    customer: frm.doc.applicant || '',
                                    company: frm.doc.company || 'JMIT',
                                    posting_date: row.due_date || frappe.datetime.get_today(),
                                    due_date: row.due_date || frappe.datetime.get_today(),
                                    currency: 'PHP',
                                    conversion_rate: 1,
                                    debit_to: '1310 - Debtors - JMIT',
                                    customer_name: frm.doc.applicant_name || frm.doc.applicant || '',
                                    taxes_and_charges: 'Philippines Tax - JMIT',
                                    against_income_account: '4110 - Sales - JMIT',
                                    cost_center: 'Main - JMIT',
                                    apply_tds: 1,
                                    taxes: [
                                        { charge_type: 'On Net Total', account_head: 'VAT - JMIT', description: 'VAT @ 12.0', rate: 12.0, cost_center: 'Main - JMIT' },
                                        { charge_type: 'Actual', account_head: 'CWT Tax - JMIT', description: 'CWT Tax - JMIT', rate: 0.0, cost_center: 'Main - JMIT' }
                                    ],
                                    items: [
                                        {
                                            item_code: 'LOAN',
                                            item_name: 'Loan EMI',
                                            description: 'Loan EMI',
                                            qty: 1,
                                            stock_qty: 1,
                                            uom: 'Nos',
                                            stock_uom: 'Nos',
                                            rate: amt,
                                            amount: amt,
                                            base_rate: amt,
                                            base_amount: amt,
                                            income_account: '4110 - Sales - JMIT',
                                            expense_account: '5111 - Cost of Goods Sold - JMIT',
                                            cost_center: 'Main - JMIT',
                                            company: frm.doc.company || 'JMIT'
                                        }
                                    ],
                                    bank_loan_app: frm.doc.name
                                }
                            }).then(function(r){
                                var si = (r && r.message) || {};
                                if(si && si.name){
                                    row.sales_invoice = si.name;
                                    row.status = 'Paid';
                                    created.push(si.name);
                                    frm.refresh_field('repayment_schedule');
                                    setTimeout(function(){ frappe.open_in_new_tab('/app/sales-invoice/' + encodeURIComponent(si.name)); }, 100);
                                } else {
                                    console.log('SI row ' + (idx-1) + ' failed', si);
                                }
                                next();
                            }).catch(function(err){
                                frappe.msgprint('Sales Invoice row ' + (idx-1) + ' failed: ' + (err && err.message ? err.message : JSON.stringify(err)));
                                console.error(err);
                                next();
                            });
                        }
                        next();
                    } else {
                        frappe.msgprint('Payment Entry creation returned empty result.');
                        console.log('PE response', pe);
                        setTimeout(function(){ frm.save(); }, 200);
                    }
                }).catch(function(err){
                    frappe.msgprint('Payment Entry creation failed: ' + (err && err.message ? err.message : JSON.stringify(err)));
                    console.error(err);
                    setTimeout(function(){ frm.save(); }, 200);
                });
            });
        }
    }
});
